import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Lemon Squeezy Payment Gateway","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Lemon Squeezy Payment Gateway | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/lemonsqueezy"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Lemon Squeezy Payment Gateway | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/lemonsqueezy"}]]},"headers":[],"relativePath":"developer-guide/lemonsqueezy.md","filePath":"developer-guide/lemonsqueezy.md","lastUpdated":1794259478000}'),n={name:"developer-guide/lemonsqueezy.md"};function d(i,e,r,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="lemon-squeezy-payment-gateway" tabindex="-1">Lemon Squeezy Payment Gateway <a class="header-anchor" href="#lemon-squeezy-payment-gateway" aria-label="Permalink to &quot;Lemon Squeezy Payment Gateway&quot;">​</a></h1><p>Lemon Squeezy is a Central payment provider (Merchant of Record) that plugs into the existing gateway-agnostic billing stack. Business logic stays in <code>BillingEngine</code> / <code>ModuleSubscriptionService</code>; Lemon Squeezy only translates between Lemon Squeezy’s JSON:API and <code>PaymentGatewayInterface</code>.</p><p>Use Lemon Squeezy when you want MoR checkout with tax/VAT handled by Lemon Squeezy. Stripe, Creem, Kelviq, and Manual remain available; switch the <strong>default</strong> gateway in Central when ready.</p><p><strong>Tenant</strong> workspace gateways are out of scope for this delivery — Central Marketplace only. Do <strong>not</strong> reuse Central <code>payment_gateways</code> credentials for tenant CRM checkout.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BillingEngine → GatewayManager → PaymentGatewayInterface</span></span>
<span class="line"><span>                                      ├── ManualGateway</span></span>
<span class="line"><span>                                      ├── StripeGateway</span></span>
<span class="line"><span>                                      ├── CreemGateway</span></span>
<span class="line"><span>                                      ├── KelviqGateway</span></span>
<span class="line"><span>                                      └── LemonSqueezyGateway  (+ LemonSqueezyClient, LemonSqueezyWebhookVerifier)</span></span></code></pre></div><p>Do <strong>not</strong> add <code>lemonsqueezy_*</code> columns. Customer ids are stored in provider-neutral <code>tenant_gateway_customers.customer_reference</code>. Checkout maps <code>payment_gateway_module_prices.gateway_price_reference</code> as the Lemon Squeezy <strong>variant id</strong>.</p><p>Lemon Squeezy’s public API cannot create products or variants. Create subscription products in the dashboard, then paste variant IDs under Product mapping. There is no <code>catalog_sync</code> capability for this driver.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li>Pull backend changes and run:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:seed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --class=Database\\\\Seeders\\\\Central\\\\PaymentGatewaySeeder</span></span></code></pre></div><ol start="2"><li><p>Configure credentials (env fallbacks <strong>or</strong> Central admin UI). Keep <code>LEMONSQUEEZY_ENV=sandbox</code> / test-mode API keys until the store is approved for live.</p></li><li><p>Map billable modules under <strong>Billing → Payment Gateways → Product mapping</strong> — paste each monthly/yearly <strong>Variant ID</strong>.</p></li><li><p>Point Lemon Squeezy webhooks to <code>POST /webhooks/gateways/lemonsqueezy</code>.</p></li><li><p>Enable Lemon Squeezy and set it as the default gateway only after a sandbox marketplace purchase succeeds.</p></li></ol><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>LEMONSQUEEZY_ENABLED</code></td><td>Seed row starts active when <code>true</code></td></tr><tr><td><code>LEMONSQUEEZY_ENV</code></td><td><code>sandbox</code> (default) | <code>live</code> / <code>production</code> (seeded <code>mode</code>)</td></tr><tr><td><code>LEMONSQUEEZY_TEST_MODE</code></td><td>Checkout <code>test_mode</code> flag while in sandbox</td></tr><tr><td><code>LEMONSQUEEZY_API_URL</code></td><td>Optional override (default <code>https://api.lemonsqueezy.com/v1</code>)</td></tr><tr><td><code>LEMONSQUEEZY_API_KEY</code></td><td>API key fallback (<code>Authorization: Bearer</code>)</td></tr><tr><td><code>LEMONSQUEEZY_STORE_ID</code></td><td>Store id required for checkout relationships</td></tr><tr><td><code>LEMONSQUEEZY_WEBHOOK_SECRET</code></td><td>Signing secret for <code>X-Signature</code> HMAC-SHA256</td></tr><tr><td><code>LEMONSQUEEZY_TIMEOUT</code> / <code>LEMONSQUEEZY_CONNECT_TIMEOUT</code></td><td>HTTP timeouts</td></tr></tbody></table><p>Prefer storing secrets in encrypted <code>payment_gateways.config</code> via the admin UI (<code>secret_key</code>, <code>webhook_secret</code>, <code>store_id</code>). Env values are fallbacks when the row is empty.</p><p>Config file: <code>config/lemonsqueezy.php</code>.</p><h2 id="sandbox-setup" tabindex="-1">Sandbox setup <a class="header-anchor" href="#sandbox-setup" aria-label="Permalink to &quot;Sandbox setup&quot;">​</a></h2><ol><li>Lemon Squeezy → Settings → API: create a <strong>Test mode</strong> API key.</li><li>Note your Store ID (Stores API or dashboard).</li><li>Central: enable Lemon Squeezy, mode <strong>sandbox</strong>, paste API key + Store ID + Webhook secret.</li><li>Create subscription products with monthly/yearly variants; map variant IDs in Product mapping.</li><li>Register webhook URL:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://api.elosync.com/webhooks/gateways/lemonsqueezy</span></span></code></pre></div><p>Subscribe at least: <code>subscription_created</code>, <code>subscription_updated</code>, <code>subscription_cancelled</code>, <code>subscription_expired</code>, <code>subscription_payment_success</code>, <code>subscription_payment_failed</code>, <code>subscription_payment_recovered</code>, <code>order_refunded</code> (logged as unsupported for ledger refunds in v1).</p><ol start="6"><li>Run <strong>Test connection</strong>, then a marketplace purchase in test mode.</li></ol><h2 id="event-mapping" tabindex="-1">Event mapping <a class="header-anchor" href="#event-mapping" aria-label="Permalink to &quot;Event mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lemon Squeezy event</th><th><code>GatewayEvent</code></th></tr></thead><tbody><tr><td><code>subscription_payment_success</code>, <code>subscription_payment_recovered</code>, <code>order_created</code></td><td><code>payment_succeeded</code></td></tr><tr><td><code>subscription_payment_failed</code></td><td><code>payment_failed</code></td></tr><tr><td><code>subscription_created</code></td><td><code>subscription_created</code></td></tr><tr><td><code>subscription_updated</code>, <code>subscription_resumed</code>, <code>subscription_paused</code>, <code>subscription_unpaused</code></td><td><code>subscription_updated</code></td></tr><tr><td><code>subscription_cancelled</code>, <code>subscription_expired</code></td><td><code>subscription_cancelled</code></td></tr><tr><td><code>order_refunded</code> (and others)</td><td><code>unsupported</code></td></tr></tbody></table><p>Custom checkout data (<code>tenant_id</code>, <code>payment_id</code>, …) is returned on webhooks as <code>meta.custom_data</code>.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Central/Billing/LemonSqueezyGatewayTest.php</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Central/Billing/LemonSqueezyWebhookTest.php</span></span></code></pre></div>`,26)])])}const m=t(n,[["render",d]]);export{u as __pageData,m as default};
